import json
from pathlib import Path
p=Path(__file__).resolve().parent
a=json.loads((p/"audit.json").read_text(encoding="utf8"))
def pct(x): return "—" if x is None else f"{100*x:.2f}%"
lines=["# KBO M0 retrospective market comparison", "", "This is a retrospective replay, not pregame receipt, live availability or an execution-price record. The M0 model trained on 2023–2025; 2025 is not held out. 2026 outcomes had already been seen; this is not a blind test. No adoption, deployment or profit claim follows.", "", "## Rule and provenance", "", "All 709 frozen forecasts are audited. A score means forecast is compared with the same official full-game product, without requiring the unrelated general-winner price to match the old replay. Forecast IDs must be unique physical KBO IDs for date/home/away; unidentified score-based IDs are excluded, as are ambiguous keys. Old archive products use handicap types 9/2; newer archives use betId 79/7, with full-game winner betId 2. First-half and other products are excluded. Official general winner scores may come from a different verified round for the same unambiguous fixture; conflicting completed scores exclude the fixture.", "", "Before inspecting outcomes, choose the lowest numeric round then matchSeq among full-game product rows for each fixture and market. Validate that chosen row only; never fall back to a later product on failure. Require a completed official original score, half-line, two prices above 1, completed non-rejected product, matching official product score and grade; model or market ties are excluded. A drawn original game does not refund a half-line handicap. M0 selects the more probable side using independent Poisson score rates; market selects the lower price. One unit per fixture; ROI includes all selected units. Drawdown uses cumulative unit profit, ordered by date, fixture ID, round, matchSeq; same-day ordering is arbitrary and not execution timing. No product/round was selected by profitability.", "", "Sources, SHA-256 hashes, all per-fixture exclusions, counts, monthly splits and each canonical row are in audit.json and canonical.json. Raw source files are external read-only dependencies; missing files or hash mismatches fail execution. Run `python scripts/validate_m0_handicap.py --output experiments/expanded-kbo-markets-20261105/old44-handicap` before `python experiments/expanded-kbo-markets-20261105/analyze.py --manifest PATH`, then `python experiments/expanded-kbo-markets-20261105/write_report.py`. Requires scipy and the source paths recorded in audit.json.", "", "## Exclusion audit", "", "```json", json.dumps(a["counts"],indent=2,ensure_ascii=False), "```", "", "Counts labelled no candidate include unidentified forecasts and must not be added to the separate missing-ID count. Raw row counts and fixture counts have different denominators.", "", "## Results: entire observed 2026 retrospective split and months", "", "| Cohort | Month | N | Model hits / rate | Model net / ROI / max drawdown | Market hits / rate | Market net / ROI / max drawdown | Disagreements; model vs market hits |", "|---|---|---:|---|---|---|---|---|" ]
for cohort, data in [("canonical "+k,v) for k,v in a["canonical"].items()]+[("old44 "+k,v) for k,v in a["old44"].items()]:
 for month, x in data.items():
  m=x["model"];q=x["market"]
  lines.append(f"| {cohort} | {month} | {m['n']} | {m['hits']} / {pct(m['hit_rate'])} | {m['net_units']:.2f} / {pct(m['roi'])} / {m['max_drawdown_units']:.2f} | {q['hits']} / {pct(q['hit_rate'])} | {q['net_units']:.2f} / {pct(q['roi'])} / {q['max_drawdown_units']:.2f} | {x['disagreements']}; {x['model_hits_on_disagreements']} vs {x['market_hits_on_disagreements']} |")
(p/"REPORT.md").write_text("\n".join(lines)+"\n",encoding="utf8")
